function renderFoot() { $('#foot').innerHTML = pager(rows().length, 'assets'); }
function renderBulk() { const n = state.selected.size, b = $('#bulk'); b.classList.toggle('open', n > 0); document.body.classList.toggle('hassel', n > 0); if (!n) return; const sel = state.assets.filter(a => state.selected.has(a.id)), out = sel.filter(a => a.status === 'DEPLOYED').length; b.innerHTML = `<b style="font-size:13px">${n} selected</b><button class="btn btn-secondary btn-sm" data-act="bulkedit">Edit…</button><button class="btn btn-secondary btn-sm" data-act="bulkmove">Move to…</button><button class="btn btn-secondary btn-sm" data-act="bulktag">Add tag…</button><button class="btn btn-secondary btn-sm deskonly" data-act="bulklabels">Print labels</button><button class="btn btn-secondary btn-sm" data-act="bulkmaint">Schedule service</button>${out ? `<button class="btn btn-secondary btn-sm" data-act="bulkreturn">Force return ${out}</button>` : ''}<button class="btn btn-secondary btn-sm" style="color:var(--t-out)" data-act="bulkretire">Retire</button><button class="btn btn-icon btn-sm" data-act="clearsel" aria-label="Clear selection">✕</button>`; }
// ---------- actions
function multiMenu(el, key, title, options) { openMenu(el, title, [...options.map(o => ({label:o, act:'ftoggle', args:`data-k="${key}" data-v="${o}"`, on:state.f[key].includes(o)})), '-', {label:'Clear', act:'fclear', args:`data-k="${key}"`}]); }
function act(name, el, ev) {
  const id = el.dataset.id, a = id ? asset(id) : null;
  switch (name) {
    case 'close': closeLayer(); break;
    case 'noop': closeLayer(); toast('Not wired in this prototype'); break;
    case 'new': closeLayer(); toast('Opens the New asset form · model first, then tag, serial, location'); break;
    case 'scan': closeLayer(); toast(isPhone() ? 'Opens the camera · scanning a tag jumps straight to that asset' : 'Focuses search · a USB scanner types the tag and Enter opens the asset'); if (!isPhone()) $('#q').focus(); break;
    case 'view': state.view = el.dataset.v; render(); break;
    case 'group': state.group = el.dataset.k; state.page = 0; render(); break;
    case 'sort': if (state.sort === el.dataset.k) state.dir = state.dir === 'asc' ? 'desc' : 'asc'; else { state.sort = el.dataset.k; state.dir = 'asc'; } render(); break;
    case 'page': state.page = Math.max(0, state.page + +el.dataset.d); render(); break;
    case 'more': state.page++; render(); break;
    case 'fmenu': { const k = el.dataset.k; if (k === 'model') multiMenu(el, 'model', 'Model', models()); if (k === 'category') multiMenu(el, 'category', 'Category', cats()); if (k === 'location') multiMenu(el, 'location', 'Location', locs()); if (k === 'condition') multiMenu(el, 'condition', 'Condition', ['Good','Fair','Poor','Needs repair']); break; }
    case 'ftoggle': { const arr = state.f[el.dataset.k], v = el.dataset.v, i = arr.indexOf(v); i >= 0 ? arr.splice(i,1) : arr.push(v); state.page = 0; state.savedView = null; render(); act('fmenu', el); break; }
    case 'fclear': state.f[el.dataset.k] = []; closeLayer(); render(); break;
    case 'kindmenu': openMenu(el, 'Kind', [['','Serialised and bulk'],['SERIALISED','Serialised only'],['BULK','Bulk only']].map(([v,l]) => ({label:l, act:'kindset', args:`data-v="${v}"`, on:state.f.kind===v}))); break;
    case 'kindset': state.f.kind = el.dataset.v; state.page = 0; closeLayer(); render(); break;
    case 'groupmenu': openMenu(el, 'Group rows by', [['','None'],['model','Model'],['location','Location'],['category','Category']].map(([v,l]) => ({label:l, act:'groupset', args:`data-v="${v}"`, on:state.groupBy===v}))); break;
    case 'groupset': state.groupBy = el.dataset.v; closeLayer(); render(); break;
    case 'clearf': state.f = { model:[], category:[], location:[], condition:[], kind:'' }; state.q = ''; $('#q').value = ''; state.savedView = null; state.page = 0; closeLayer(); render(); break;
    case 'viewsmenu': openMenu(el, 'Views', [{sh:'Saved views · each one is a URL you can share'}, ...VIEWS.map((v,i) => ({label:v.name, act:'applyview', args:`data-i="${i}"`, on:state.savedView===v.name})), '-', {label:'Save current view…', act:'saveview'}, ...(state.savedView ? [{label:'Clear view', act:'clearf'}] : [])]); break;
    case 'applyview': { const v = VIEWS[+el.dataset.i]; state.f = { model:[], category:[], location:[], condition:[], kind:'', ...(v.f||{}) }; state.group = v.group || 'all'; state.savedView = v.name; state.page = 0; closeLayer(); render(); toast(`View “${v.name}” · the filters are in the URL, so the link is the view`); break; }
    case 'saveview': closeLayer(); openDialog(`<div class="hd"><div class="t-overline">Views</div><h2 style="font-size:18px">Save current view</h2></div><div class="bd">${field('Name', `<input id="v-name" placeholder="e.g. Audio on the floor" value="">`)}<label class="ib t-small" style="gap:8px;margin-top:10px;cursor:pointer"><span class="sw" data-act="sw"><i></i></span>Make this my default for Assets</label></div><div class="ft"><div style="flex:1"></div><button class="btn btn-secondary" data-act="close">Cancel</button><button class="btn btn-primary" data-act="saveviewgo">Save</button></div>`, d => $('#v-name', d).focus()); break;
    case 'sw': el.classList.toggle('on'); break;
    case 'saveviewgo': { const nm = $('#v-name', body).value.trim() || 'Untitled view'; VIEWS.push({ name:nm, f:{ ...state.f }, group:state.group }); state.savedView = nm; closeLayer(); render(); toast(`Saved “${nm}”`); break; }
    case 'pagemenu': openMenu(el, 'Assets', [{label:'Models', act:'noop', small:'18'},{label:'Kits', act:'noop', small:'6'},{label:'Locations', act:'noop'},'-',{label:'Import CSV…', act:'noop'},{label:'Export this view (CSV)', act:'noop'},{label:'Print labels for this view', act:'noop'},'-',{label:'Columns', act:'colsmenu'},{label:'Show retired', act:'showretired', on:state.group==='retired'}]); break;
    case 'colsmenu': openMenu(el, 'Columns', [{label:'Value', act:'coltoggle', args:'data-c="value"', on:state.cols.value},{label:'Tags', act:'coltoggle', args:'data-c="tags"', on:state.cols.tags},{label:'Owner', act:'coltoggle', args:'data-c="owner"', on:state.cols.owner},{sh:'Tag, model, serial, status, condition, location, next due and job are always shown'}]); break;
    case 'coltoggle': state.cols[el.dataset.c] = !state.cols[el.dataset.c]; closeLayer(); render(); break;
    case 'showretired': state.group = state.group === 'retired' ? 'all' : 'retired'; closeLayer(); render(); break;
    case 'open': if (ev && ev.target.closest('.cb,.dots,a')) break; closeLayer(); toast(`Opens ${esc(a.tag)} · ${esc(a.model)}`); break;
    case 'select': { if (ev && ev.shiftKey && state.lastSel) { const order = rows().map(x => x.id), i1 = order.indexOf(state.lastSel), i2 = order.indexOf(id); for (const k of order.slice(Math.min(i1,i2), Math.max(i1,i2)+1)) state.selected.add(k); } else state.selected.has(id) ? state.selected.delete(id) : state.selected.add(id); state.lastSel = id; render(); break; }
    case 'selall': { const pr = rows().slice(state.page * state.size, (state.page + 1) * state.size); const all = pr.every(x => state.selected.has(x.id)); pr.forEach(x => all ? state.selected.delete(x.id) : state.selected.add(x.id)); render(); break; }
    case 'clearsel': state.selected.clear(); render(); break;
    case 'rowmenu': openMenu(el, `${a.tag} · ${a.model}`, [{label:'Open', act:'open', args:`data-id="${a.id}"`},{label:'Edit…', act:'noop'},...(a.job ? [{label:`Job ${a.job.num}`, href:OV, small:'Overview'}] : []),'-',{label:'Move to…', act:'movemenu', args:`data-id="${a.id}"`},{label:'Schedule service…', act:'maintone', args:`data-id="${a.id}"`},{label:'Print label', act:'noop'},{label:'Duplicate…', act:'noop'},'-',...(a.status === 'DEPLOYED' ? [{label:'Force return', act:'returnone', args:`data-id="${a.id}"`}] : []),{label:a.status === 'RETIRED' ? 'Reinstate' : 'Retire…', act:'retireone', args:`data-id="${a.id}"`, danger:a.status !== 'RETIRED'}]); break;
    case 'movemenu': openMenu(el, `Move ${a.tag} to`, locs().filter(l => l !== 'On job').map(l => ({label:l, act:'moveone', args:`data-id="${a.id}" data-v="${l}"`, on:a.location===l}))); break;
    case 'moveone': { const undo = snapshot(); a.location = el.dataset.v; closeLayer(); render(); toast(`${esc(a.tag)} moved to ${esc(a.location)}`, undo); break; }
    case 'maintone': { const undo = snapshot(); a.maintDue = addD(TODAY, 3); a.status = a.status === 'AVAILABLE' ? 'IN_MAINTENANCE' : a.status; closeLayer(); render(); toast(`Service scheduled for ${esc(a.tag)} · ${fmtD(a.maintDue)}`, undo); break; }
    case 'returnone': { const undo = snapshot(); a.status = 'AVAILABLE'; a.job = null; a.location = 'Warehouse A'; closeLayer(); render(); toast(`${esc(a.tag)} returned to Warehouse A · the job's line keeps its history`, undo); break; }
    case 'retireone': { const undo = snapshot(); a.status = a.status === 'RETIRED' ? 'AVAILABLE' : 'RETIRED'; closeLayer(); render(); toast(a.status === 'RETIRED' ? `${esc(a.tag)} retired · hidden from availability, history kept` : `${esc(a.tag)} reinstated`, undo); break; }
    case 'bulkedit': closeLayer(); openDialog(`<div class="hd"><div class="t-overline">${state.selected.size} assets</div><h2 style="font-size:18px">Edit together</h2></div><div class="bd" style="display:grid;gap:12px">${field('Condition', `<select id="b-cond">${opt('', 'Leave as is')}${['Good','Fair','Poor','Needs repair'].map(c => opt(c, c)).join('')}</select>`)}${field('Owner', `<select id="b-owner">${opt('', 'Leave as is')}${opt('Owned','Owned')}${opt('Sub-hire (Chameleon)','Sub-hire (Chameleon)')}</select>`)}<div class="t-micro muted">Only the fields you change are written · tag and serial stay unique per asset</div></div><div class="ft"><div style="flex:1"></div><button class="btn btn-secondary" data-act="close">Cancel</button><button class="btn btn-primary" data-act="bulkeditgo">Save</button></div>`); break;
    case 'bulkeditgo': { const c = $('#b-cond', body).value, o = $('#b-owner', body).value; const undo = snapshot(); const cnt = state.selected.size; state.assets.forEach(x => { if (state.selected.has(x.id)) { if (c) x.condition = c; if (o) x.owner = o; } }); state.selected.clear(); closeLayer(); render(); toast(`${cnt} assets updated`, undo); break; }
    case 'bulkmove': openMenu(el, `Move ${state.selected.size} to`, locs().filter(l => l !== 'On job').map(l => ({label:l, act:'bulkmovego', args:`data-v="${l}"`}))); break;
    case 'bulkmovego': { const undo = snapshot(); const cnt = state.selected.size; state.assets.forEach(x => { if (state.selected.has(x.id) && x.status !== 'DEPLOYED') x.location = el.dataset.v; }); state.selected.clear(); closeLayer(); render(); toast(`${cnt} assets moved to ${esc(el.dataset.v)} · deployed ones stay on their job`, undo); break; }
    case 'bulktag': closeLayer(); openDialog(`<div class="hd"><div class="t-overline">${state.selected.size} assets</div><h2 style="font-size:18px">Add a tag</h2></div><div class="bd">${field('Tag', `<input id="t-tag" placeholder="e.g. touring" value="">`)}</div><div class="ft"><div style="flex:1"></div><button class="btn btn-secondary" data-act="close">Cancel</button><button class="btn btn-primary" data-act="bulktaggo">Add</button></div>`, d => $('#t-tag', d).focus()); break;
    case 'bulktaggo': { const t = $('#t-tag', body).value.trim(); if (!t) break; const undo = snapshot(); const cnt = state.selected.size; state.assets.forEach(x => { if (state.selected.has(x.id) && !x.tags.includes(t)) x.tags.push(t); }); state.selected.clear(); closeLayer(); render(); toast(`“${t}” added to ${cnt} assets`, undo); break; }
    case 'bulklabels': { const cnt = state.selected.size; closeLayer(); toast(`Label sheet for ${cnt} assets · opens the print dialog`); break; }
    case 'bulkmaint': { const undo = snapshot(); const cnt = state.selected.size; state.assets.forEach(x => { if (state.selected.has(x.id)) { x.maintDue = addD(TODAY, 3); if (x.status === 'AVAILABLE') x.status = 'IN_MAINTENANCE'; } }); state.selected.clear(); closeLayer(); render(); toast(`Service scheduled for ${cnt} assets · ${fmtD(addD(TODAY, 3))}`, undo); break; }
    case 'bulkreturn': { const undo = snapshot(); let cnt = 0; state.assets.forEach(x => { if (state.selected.has(x.id) && x.status === 'DEPLOYED') { x.status = 'AVAILABLE'; x.job = null; x.location = 'Warehouse A'; cnt++; } }); state.selected.clear(); closeLayer(); render(); toast(`${cnt} assets force-returned to Warehouse A`, undo); break; }
    case 'bulkretire': { const cnt = state.selected.size; closeLayer(); openDialog(`<div class="hd"><div class="t-overline">Retire</div><h2 style="font-size:18px">Retire ${cnt} assets?</h2></div><div class="bd"><div class="t-small" style="line-height:1.5">Retired gear leaves availability and every picker, but keeps its history, documents and test &amp; tag record. Anything currently on a job is skipped. You can reinstate from the Retired segment.</div></div><div class="ft"><div style="flex:1"></div><button class="btn btn-secondary" data-act="close">Keep them</button><button class="btn btn-secondary" style="color:var(--t-out)" data-act="bulkretirego">Retire ${cnt}</button></div>`); break; }
    case 'bulkretirego': { const undo = snapshot(); let cnt = 0; state.assets.forEach(x => { if (state.selected.has(x.id) && x.status !== 'DEPLOYED') { x.status = 'RETIRED'; cnt++; } }); state.selected.clear(); closeLayer(); render(); toast(`${cnt} assets retired`, undo); break; }
    case 'undo': if (state.undo) { state.undo(); state.undo = null; } $('#toast').classList.remove('open'); break;
    case 'toastclose': $('#toast').classList.remove('open'); break;
  }
}
document.addEventListener('input', ev => { if (ev.target.id === 'q') { state.q = ev.target.value; state.page = 0; state.savedView = null; render(); } });
render();
